// Bundle the bridge modules into a single import-free ES module (bundle.js).
//
// WHY: Sciter cannot resolve relative module imports when the document path
// contains a space ("web-view-test 2") — its base URL is malformed, so `./x.js`
// stays literal ("Unknown module 'file:./x.js'"). A single import-free file loaded
// by absolute path needs no relative resolution and works. The multi-file source
// stays for the Node tests.
//
// Run after changing any module:  node demo/build/build-bundle.mjs
// A drift guard (demo/test/bundle.test.mjs) fails if bundle.js is stale.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url)); // demo/build/

// dependency order (paths relative to demo/build/): the shipped bridge lives
// under ../../bridge; demo templates under ../templates. Each module only
// references names defined above it.
const ORDER = [
  "../../bridge/core/contract.mjs",
  "../../bridge/core/template-client.mjs",
  "../../bridge/core/inject.mjs",
  "../../bridge/core/render.mjs",
  "../../bridge/core/notification.mjs",
  "../templates/notification-template.js",
  "../templates/skeleton-template.js",
  "../../bridge/sciter/sciter-host.mjs",
];

// public API the host page imports from the bundle
const PUBLIC_EXPORTS = ["showNotification", "notificationTemplate", "skeletonTemplate", "TEMPLATE_CLIENT", "TEMPLATE_STYLES"];

function stripModule(src) {
  return src
    .split("\n")
    // drop single-line `import ... from "...";` (all our imports are single-line)
    .filter((line) => !/^\s*import\s.+from\s+["'][^"']+["'];?\s*$/.test(line))
    // turn `export const/function/class ...` into a plain declaration
    .map((line) => line.replace(/^(\s*)export\s+(?=(const|function|class|let|var|async)\b)/, "$1"))
    .join("\n");
}

export function buildBundle() {
  const parts = [
    "// AUTO-GENERATED by demo/build/build-bundle.mjs — DO NOT EDIT.",
    "// Source of truth: bridge/core + bridge/sciter (ship) and demo/templates. Rebuild with:",
    "//   node demo/build/build-bundle.mjs",
    "",
  ];
  for (const file of ORDER) {
    parts.push(`// ===== ${file.replace(/^(\.\.\/)+/, "")} =====`);
    parts.push(stripModule(readFileSync(join(HERE, file), "utf8")).trim());
    parts.push("");
  }
  parts.push(`export { ${PUBLIC_EXPORTS.join(", ")} };`);
  parts.push("");
  return parts.join("\n");
}

const isMain = process.argv[1] && process.argv[1].replace(/\\/g, "/").endsWith("build-bundle.mjs");
if (isMain) {
  writeFileSync(join(HERE, "bundle.js"), buildBundle());
  console.log("wrote demo/build/bundle.js");
}
